select.if:
SELECT /** selectMasterWmGrStockGrCreList */ '발주' AS STATUS, PO.PO_NO , MAX(TO_CHAR(TO_DATE(HD.PO_CREATE_DATE,'YYYYMMDD'),'YYYY/MM/DD')) AS PO_CREATE_DATE, '' AS DS_DATE, COUNT(PO.PO_SEQ) AS COUNT, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = PR.AGENT)) AS AGENT_NAME, MAX(PO.LEGACY_PO_NO) AS LEGACY_PO_NO, '' AS IV_NO , MAX(TO_CHAR(TO_DATE(PO.RD_DATE,'YYYYMMDD'),'YYYY/MM/DD')) AS RD_DATE, MAX(PR.ADD_USER_NAME) AS PR_ADD_USER_NAME, SUM(PO.ITEM_AMT) AS ITEM_AMT , MAX(PR.AGENT) AS AGENT_CODE, MAX(PO.BUYER) AS BUYER, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = PO.BUYER)) AS BUYER_NAME, MAX(PR.ADD_USER_TEL) AS PR_USER_NAME, MAX(HD.PO_REMARK) AS POHD_REMARK, MAX((SELECT TEL_NO FROM ICOMCMPY WHERE COM_CODE = PR.AGENT)) AS AGENT_TEL FROM ICOMPODT PO , ICOMPRDT PR , ICOMPOHD HD
PO.BUYER=#{st_warehouse_code} AND PO.IV_QTY ^= PO.ITEM_QTY AND HD.STATUS ^='D' AND PO.STATUS ^='D' AND PR.STATUS ^='D' AND PO.PR_NO = PR.PR_NO AND PO.PR_SEQ = PR.PR_SEQ AND PO.BUYER = PR.BUYER AND PO.BUYER = HD.BUYER AND PO.PO_NO = HD.PO_NO
AND PO.RD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND (PO.PO_NO LIKE #{st_po_no}||'%' OR PO.LEGACY_PO_NO LIKE #{st_po_no}||'%')
AND PO.PO_NO = #{st_iv_no}
AND PR.AGENT = #{st_agent_code}
GROUP BY PO.BUYER,PO.PO_NO

SELECT DECODE(MAX(PO.ITEM_QTY),MAX(IV.INV_QTY),'입고예정','분할입고예정') AS STATUS, IV.PO_NO AS PO_NO, MAX(TO_CHAR(TO_DATE(POHD.PO_CREATE_DATE,'YYYYMMDD'),'YYYY/MM/DD')) AS PO_CREATE_DATE, MAX(TO_CHAR(TO_DATE(IV.DS_DATE,'YYYYMMDD'),'YYYY/MM/DD')) AS DS_DATE, COUNT(IV.INV_SEQ) AS COUNT, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = IVHD.AGENT)) AS AGENT_NAME, MAX(PO.LEGACY_PO_NO) AS LEGACY_PO_NO, MAX(IV.INV_NO) AS IV_NO, MAX(TO_CHAR(TO_DATE(PO.RD_DATE,'YYYYMMDD'),'YYYY/MM/DD')) AS RD_DATE, MAX(PR.ADD_USER_NAME) AS PR_ADD_USER_NAME, SUM(IV.ITEM_AMT) AS ITEM_AMT, MAX(IVHD.AGENT) AS AGENT_CODE, IV.BUYER, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = PO.BUYER)) AS BUYER_NAME, MAX(PR.ADD_USER_TEL) AS PR_USER_NAME, MAX(POHD.PO_REMARK) AS POHD_REMARK, MAX((SELECT TEL_NO FROM ICOMCMPY WHERE COM_CODE = IVHD.AGENT)) AS AGENT_TEL FROM ICOMIVDT IV , ICOMPODT PO , ICOMIVHD IVHD , ICOMPRDT PR ,ICOMPOHD POHD
PO.BUYER = IV.BUYER AND PO.PO_NO = IV.PO_NO AND PO.PO_SEQ = IV.PO_SEQ AND IV.INV_NO = IVHD.INV_NO AND IV.SELLER = IVHD.SELLER AND IV.BUYER = IVHD.BUYER AND PO.BUYER = PR.BUYER AND PO.PR_NO = PR.PR_NO AND PO.PR_SEQ = PR.PR_SEQ AND PO.PO_NO = POHD.PO_NO AND PO.BUYER = POHD.BUYER AND IV.WMS_GR_QTY = 0 AND IV.STATUS ^='D' AND PO.STATUS ^='D' AND IVHD.STATUS ^='D' AND PR.STATUS ^='D' AND POHD.STATUS ^='D' AND IV.BUYER =#{st_warehouse_code}
AND IV.DS_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND IV.INV_QTY > 0
AND PO.ITEM_QTY ^= IV.INV_QTY
AND (PO.PO_NO LIKE #{st_po_no}||'%' OR PO.LEGACY_PO_NO LIKE #{st_po_no}||'%')
AND IV.INV_NO LIKE #{st_iv_no}||'%'
AND PR.AGENT = #{st_agent_code}
GROUP BY IV.BUYER,IV.PO_NO,IV.INV_NO

mapper.select:

					 /** selectMasterWmGrStockGrCre_GR_QTY */
					 SELECT  INV_NO
                      			,WMS_GR_QTY
                      			,BUYER
                     			 ,PO_NO
                       FROM ICOMIVDT
					 WHERE BUYER = #{BUYER}
					    AND  SELLER =#{SELLER}    
					    AND  PO_NO = #{ PO_NO } 
                        AND  INV_NO = #{IV_NO} 
                        AND  STATUS != 'D'
                        AND   WMS_GR_QTY <> 0

mapper.update:

/**updataeIICOMIVDT_WMS_GR_QTY */
		  UPDATE ICOMIVDT IVDT SET  
         IVDT.WMS_GR_QTY = NVL(IVDT.INV_QTY,0),  
         IVDT.WMS_GR_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'),  
         IVDT.WMS_GR_USER_ID = #{st_user_id}    
   WHERE IVDT.INV_NO = #{IV_NO} 	   
     AND IVDT.BUYER = #{BUYER}          
     AND IVDT.PO_NO = #{PO_NO}   
     AND IVDT.STATUS <> 'D'   
     AND NVL(IVDT.WMS_GR_QTY, 0) = 0
